          svg: `<svg viewBox="0 0 1100 1100" xmlns="http://www.w3.org/2000/svg"><rect width="1100" height="1100" fill="#1a1a2e"/><text x="550" y="70" text-anchor="middle" fill="#ffd700" font-size="38" font-weight="bold" font-family="Arial">Quiz: First of Next Month</text><text x="550" y="130" text-anchor="middle" fill="#888" font-size="22" font-family="Arial">A1 = 2024-06-18</text><rect x="100" y="200" width="900" height="160" fill="#10b981" opacity="0.2" stroke="#10b981" stroke-width="3" rx="12"/><text x="550" y="245" text-anchor="middle" fill="#10b981" font-size="26" font-weight="bold" font-family="Arial">=EOMONTH(A1, 0) + 1</text><text x="550" y="295" text-anchor="middle" fill="#ffffff" font-size="20" font-family="Arial">EOMONTH(A1,0) = 2024-06-30 (last day of A1's month)</text><text x="550" y="330" text-anchor="middle" fill="#ffd700" font-size="22" font-family="Arial">+1 = 2024-07-01 CORRECT</text><rect x="100" y="395" width="900" height="120" fill="#ef4444" opacity="0.2" stroke="#ef4444" stroke-width="3" rx="12"/><text x="550" y="435" text-anchor="middle" fill="#ef4444" font-size="22" font-weight="bold" font-family="Arial">=DATE(YEAR(A1), MONTH(A1), 1)</text><text x="550" y="475" text-anchor="middle" fill="#ffffff" font-size="18" font-family="Arial">= 2024-06-01 (first of THIS month — wrong)</text><rect x="100" y="540" width="900" height="120" fill="#ef4444" opacity="0.2" stroke="#ef4444" stroke-width="3" rx="12"/><text x="550" y="580" text-anchor="middle" fill="#ef4444" font-size="22" font-weight="bold" font-family="Arial">=A1 + 30</text><text x="550" y="620" text-anchor="middle" fill="#ffffff" font-size="18" font-family="Arial">= 2024-07-18 (not the FIRST, and Feb breaks)</text><rect x="100" y="685" width="900" height="120" fill="#ef4444" opacity="0.2" stroke="#ef4444" stroke-width="3" rx="12"/><text x="550" y="725" text-anchor="middle" fill="#ef4444" font-size="22" font-weight="bold" font-family="Arial">=EOMONTH(A1, 1)</text><text x="550" y="765" text-anchor="middle" fill="#ffffff" font-size="18" font-family="Arial">= 2024-07-31 (LAST of next month, not first)</text><rect x="100" y="850" width="900" height="180" fill="#ffd700" opacity="0.15" stroke="#ffd700" stroke-width="3" rx="12"/><text x="550" y="900" text-anchor="middle" fill="#ffd700" font-size="24" font-weight="bold" font-family="Arial">Pattern to memorize</text><text x="550" y="945" text-anchor="middle" fill="#ffffff" font-size="20" font-family="monospace">EOMONTH(date, n) + 1</text><text x="550" y="985" text-anchor="middle" fill="#ffffff" font-size="20" font-family="Arial">= first day of (n+1) months from date</text></svg>`,
